update qxx_sal_order
order_code = #{orderCode}, order_name = #{orderName}, order_type = #{orderType}, client_id = #{clientId}, client_code = #{clientCode}, client_name = #{clientName}, client_nick = #{clientNick}, client_order_code = #{clientOrderCode}, production_remark = #{productionRemark}, salesperson = #{salesperson}, business_line = #{businessLine}, sample_flag = #{sampleFlag}, outsource_flag = #{outsourceFlag}, package_flag = #{packageFlag}, source_system = #{sourceSystem}, external_order_id = #{externalOrderId}, external_order_no = #{externalOrderNo}, external_version = #{externalVersion}, accept_status = #{acceptStatus}, accept_time = #{acceptTime}, reject_reason = #{rejectReason}, reject_by = #{rejectBy}, reject_time = #{rejectTime}, sync_status = #{syncStatus}, sync_time = #{syncTime}, order_date = #{orderDate}, request_date = #{requestDate}, total_amount = #{totalAmount}, payment_method = #{paymentMethod}, status = #{status}, approve_by = #{approveBy}, approve_time = #{approveTime}, approve_remark = #{approveRemark}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where order_id = #{orderId}

update qxx_sal_order
set reject_reason = null, reject_by = null, reject_time = null,
    update_by = #{updateBy}, update_time = #{updateTime}
where order_id = #{orderId} and factory_id = #{factoryId}

update qxx_sal_order
set sync_status = #{syncStatus}, sync_time = #{syncTime}
where order_id = #{orderId} and factory_id = #{factoryId}

update qxx_sal_order
set status = 'PRODUCING', update_by = #{updateBy}, update_time = #{updateTime}
where order_id = #{orderId} and factory_id = #{factoryId} and status = 'CONFIRMED'

update qxx_sal_order o
set o.status = 'SHIPPED', o.update_by = #{updateBy}, o.update_time = #{updateTime}
where o.order_id = #{orderId}
  and o.factory_id = #{factoryId}
  and o.status in ('CONFIRMED', 'PRODUCING')
  and not exists (
      select 1 from qxx_sal_order_line l
      left join (
          select sl.sales_order_line_id as sol_id, sum(b.quantity) as shipped_qty
          from qxx_wm_product_sales s
          inner join qxx_wm_product_sales_line sl on sl.sales_id = s.sales_id and sl.factory_id = s.factory_id
          inner join qxx_wm_product_sales_box b on b.line_id = sl.line_id and b.factory_id = sl.factory_id
                                               and b.status = 'SHIPPED'
          where s.sales_order_id = #{orderId}
            and s.factory_id = #{factoryId}
            and s.status <> 'CANCELED'
          group by sl.sales_order_line_id
      ) x on x.sol_id = l.line_id
      where l.order_id = #{orderId}
        and l.factory_id = #{factoryId}
        and l.quantity > coalesce(x.shipped_qty, 0)
  )

update qxx_sal_order o
set o.status = case
        when exists (
            select 1 from qxx_sal_order_line l2
            inner join qxx_pro_workorder w2 on w2.sales_order_line_id = l2.line_id
                and w2.factory_id = l2.factory_id and w2.status != 'CANCEL'
            where l2.order_id = #{orderId} and l2.factory_id = #{factoryId}
        ) then 'PRODUCING' else 'CONFIRMED' end,
    o.update_by = #{updateBy}, o.update_time = #{updateTime}
where o.order_id = #{orderId}
  and o.factory_id = #{factoryId}
  and o.status = 'SHIPPED'
  and exists (
      select 1 from qxx_sal_order_line l
      left join (
          select sl.sales_order_line_id as sol_id, sum(b.quantity) as shipped_qty
          from qxx_wm_product_sales s
          inner join qxx_wm_product_sales_line sl on sl.sales_id = s.sales_id and sl.factory_id = s.factory_id
          inner join qxx_wm_product_sales_box b on b.line_id = sl.line_id and b.factory_id = sl.factory_id
                                               and b.status = 'SHIPPED'
          where s.sales_order_id = #{orderId}
            and s.factory_id = #{factoryId}
            and s.status <> 'CANCELED'
          group by sl.sales_order_line_id
      ) x on x.sol_id = l.line_id
      where l.order_id = #{orderId}
        and l.factory_id = #{factoryId}
        and l.quantity > coalesce(x.shipped_qty, 0)
  )

update qxx_sal_order
set status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}
where order_id = #{orderId}
